function parseFlex(sh){
  if(sh==null) return {grow:0,shrink:1,basis:'auto'};
  if(typeof sh==='number') return {grow:sh,shrink:1,basis:'0%'};
  var s=String(sh).trim();
  if(s==='none') return {grow:0,shrink:0,basis:'auto'};
  if(s==='auto') return {grow:1,shrink:1,basis:'auto'};
  if(s==='initial'||s==='') return {grow:0,shrink:1,basis:'auto'};
  var parts=s.split(/\s+/);
  var nums=[], basis=null;
  for(var i=0;i<parts.length;i++){
    var p=parts[i];
    if(/^[0-9.]+$/.test(p) && nums.length<2 && basis===null) nums.push(parseFloat(p));
    else basis=p;
  }
  var grow=nums.length>0?nums[0]:1;
  var shrink=nums.length>1?nums[1]:1;
  if(basis===null) basis = nums.length>0 ? '0%' : 'auto';
  return {grow:grow, shrink:shrink, basis:basis};
}

function resolveBasis(basis, contentSize, mainSize){
  if(basis==null||basis==='auto'||basis==='content') return contentSize;
  if(typeof basis==='number') return basis;
  var s=String(basis).trim();
  if(/%$/.test(s)) return mainSize*(parseFloat(s)||0)/100;
  var v=parseFloat(s);
  return isFinite(v)?v:contentSize;
}

function normItems(items){
  var out=[];
  for(var i=0;i<items.length;i++){
    var it=items[i]||{};
    var f = it.flex!=null ? parseFlex(it.flex)
          : {grow: it.grow||0,
             shrink: it.shrink==null?1:it.shrink,
             basis: it.basis==null?'auto':it.basis};
    out.push({i:i, w:it.w==null?100:it.w, h:it.h==null?40:it.h,
              grow:f.grow, shrink:f.shrink, basis:f.basis,
              alignSelf:it.alignSelf||null, order:it.order||0,
              label:it.label==null?String(i+1):it.label});
  }
  return out;
}

function orderItems(items){
  var idx=items.map(function(x,k){ return {x:x,k:k}; });
  idx.sort(function(a,b){ return (a.x.order-b.x.order) || (a.k-b.k); });
  return idx.map(function(e){ return e.x; });
}

function breakLines(items, hyp, mainSize, gap, wrap){
  if(wrap==='nowrap') return [{items:items, hyp:hyp}];
  var lines=[], cur=[], curH=[], acc=0;
  for(var i=0;i<items.length;i++){
    var need = hyp[i] + (cur.length?gap:0);
    if(cur.length && acc+need > mainSize + 0.001){
      lines.push({items:cur, hyp:curH}); cur=[]; curH=[]; acc=0; need=hyp[i];
    }
    cur.push(items[i]); curH.push(hyp[i]); acc+=need;
  }
  if(cur.length) lines.push({items:cur, hyp:curH});
  return lines;
}

function flexLine(line, mainSize, gap){
  var n=line.items.length;
  var sizes=line.hyp.slice();
  var total=0; for(var i=0;i<n;i++) total+=sizes[i];
  var free = mainSize - total - gap*(n-1);
  if(free > 0.001){
    var tg=0; for(var a=0;a<n;a++) tg+=line.items[a].grow;
    if(tg>0) for(var b=0;b<n;b++) sizes[b] += free*line.items[b].grow/tg;
  } else if(free < -0.001){
    var scaled=0;
    for(var c=0;c<n;c++) scaled += line.items[c].shrink*line.hyp[c];
    if(scaled>0) for(var d=0;d<n;d++){
      sizes[d] += free*(line.items[d].shrink*line.hyp[d])/scaled;
      if(sizes[d]<0) sizes[d]=0;
    }
  }
  return sizes;
}

function distribute(mode, free, n, gap){
  var start=0, between=gap;
  if(free<0) free=0;
  if(mode==='flex-end'||mode==='end') start=free;
  else if(mode==='center') start=free/2;
  else if(mode==='space-between') { if(n>1) between=gap+free/(n-1); }
  else if(mode==='space-around'){ var ea=free/n; start=ea/2; between=gap+ea; }
  else if(mode==='space-evenly'){ var ee=free/(n+1); start=ee; between=gap+ee; }
  return {start:start, between:between};
}

function crossPos(mode, lineStart, lineCross, itemCross){
  if(mode==='flex-end'||mode==='end') return lineStart + lineCross - itemCross;
  if(mode==='center') return lineStart + (lineCross-itemCross)/2;
  return lineStart;
}

function layout(cfg, items, box){
  cfg = cfg||{};
  var dir = cfg.direction||'row';
  var isRow = dir==='row'||dir==='row-reverse';
  var revMain = dir==='row-reverse'||dir==='column-reverse';
  var wrap = cfg.wrap||'nowrap';
  var gap = cfg.gap||0;
  var justify = cfg.justify||'flex-start';
  var align = cfg.align||'stretch';
  var alignContent = cfg.alignContent||'stretch';
  var mainSize = isRow ? box.w : box.h;
  var crossSize = isRow ? box.h : box.w;

  var norm = orderItems(normItems(items));
  var hyp = norm.map(function(it){
    return resolveBasis(it.basis, isRow?it.w:it.h, mainSize);
  });
  var lines = breakLines(norm, hyp, mainSize, gap, wrap);

  var lineCross = lines.map(function(ln){
    var m=0;
    for(var i=0;i<ln.items.length;i++){ var cv = isRow?ln.items[i].h:ln.items[i].w; if(cv>m) m=cv; }
    return m;
  });
  var totalCross=0; for(var q=0;q<lineCross.length;q++) totalCross+=lineCross[q];
  var crossFree = crossSize - totalCross - gap*(lines.length-1);
  var stretchLines = (alignContent==='stretch' && lines.length>0 && crossFree>0);
  if(stretchLines){
    var add = crossFree/lines.length;
    for(var w2=0;w2<lineCross.length;w2++) lineCross[w2]+=add;
    crossFree = 0;
  }
  var cd = distribute(alignContent==='stretch'?'flex-start':alignContent, crossFree, lines.length, gap);

  var out=[];
  var cy = cd.start;
  var order = (wrap==='wrap-reverse') ? lines.slice().reverse() : lines;
  var orderCross = (wrap==='wrap-reverse') ? lineCross.slice().reverse() : lineCross;

  for(var li=0; li<order.length; li++){
    var ln=order[li];
    var sizes=flexLine(ln, mainSize, gap);
    var used=0; for(var s2=0;s2<sizes.length;s2++) used+=sizes[s2];
    var mFree = mainSize - used - gap*(sizes.length-1);
    var md = distribute(justify, mFree, sizes.length, gap);
    var mp = md.start;
    for(var k=0;k<ln.items.length;k++){
      var it=ln.items[k];
      var mainLen=sizes[k];
      var selfAlign = it.alignSelf && it.alignSelf!=='auto' ? it.alignSelf : align;
      var natCross = isRow?it.h:it.w;
      var crossLen = (selfAlign==='stretch') ? orderCross[li] : natCross;
      var cp = crossPos(selfAlign, cy, orderCross[li], crossLen);
      var mStart = revMain ? (mainSize - mp - mainLen) : mp;
      out.push(isRow
        ? {i:it.i, label:it.label, x:round2(mStart), y:round2(cp), w:round2(mainLen), h:round2(crossLen)}
        : {i:it.i, label:it.label, x:round2(cp), y:round2(mStart), w:round2(crossLen), h:round2(mainLen)});
      mp += mainLen + md.between;
    }
    cy += orderCross[li] + cd.between;
  }
  out.sort(function(a,b){ return a.i-b.i; });
  return {boxes:out, lines:lines.length, lineCross:lineCross.map(round2)};
}

function round2(v){ return Math.round(v*100)/100; }

function containerCss(cfg){
  cfg=cfg||{};
  var L=['display: flex;'];
  if(cfg.direction && cfg.direction!=='row') L.push('flex-direction: '+cfg.direction+';');
  if(cfg.wrap && cfg.wrap!=='nowrap') L.push('flex-wrap: '+cfg.wrap+';');
  if(cfg.justify && cfg.justify!=='flex-start') L.push('justify-content: '+cfg.justify+';');
  if(cfg.align && cfg.align!=='stretch') L.push('align-items: '+cfg.align+';');
  if(cfg.wrap && cfg.wrap!=='nowrap' && cfg.alignContent && cfg.alignContent!=='stretch')
    L.push('align-content: '+cfg.alignContent+';');
  if(cfg.gap) L.push('gap: '+cfg.gap+'px;');
  return '.container {\n  ' + L.join('\n  ') + '\n}';
}

function itemCss(it, sel){
  it=it||{};
  var f = it.flex!=null ? parseFlex(it.flex)
        : {grow:it.grow||0, shrink:it.shrink==null?1:it.shrink, basis:it.basis==null?'auto':it.basis};
  var basis = typeof f.basis==='number' ? f.basis+'px' : f.basis;
  var L=['flex: '+f.grow+' '+f.shrink+' '+basis+';'];
  if(it.alignSelf && it.alignSelf!=='auto') L.push('align-self: '+it.alignSelf+';');
  if(it.order) L.push('order: '+it.order+';');
  return (sel||'.item') + ' {\n  ' + L.join('\n  ') + '\n}';
}

function fullCss(cfg, items){
  var parts=[containerCss(cfg)];
  var norm=normItems(items||[]);
  for(var i=0;i<norm.length;i++){
    var it=norm[i];
    var isDefault = it.grow===0 && it.shrink===1 && (it.basis==='auto') && !it.alignSelf && !it.order;
    if(!isDefault) parts.push(itemCss(items[i], '.item-'+(i+1)));
  }
  return parts.join('\n\n');
}

function lint(cfg, items, box){
  cfg=cfg||{}; items=items||[]; box=box||{w:640,h:220};
  var w=[];
  var norm=normItems(items);
  var isRow=(cfg.direction||'row').indexOf('row')===0;
  var mainSize=isRow?box.w:box.h;
  var gap=cfg.gap||0;
  var sum=0;
  for(var i=0;i<norm.length;i++) sum += resolveBasis(norm[i].basis, isRow?norm[i].w:norm[i].h, mainSize);
  sum += gap*Math.max(0,norm.length-1);
  var noShrink = norm.length>0 && norm.every(function(x){ return x.shrink===0; });
  if((cfg.wrap||'nowrap')==='nowrap' && sum>mainSize+0.5 && noShrink)
    w.push({level:'error', msg:'nowrap + flex-shrink:0 且内容总宽 '+round2(sum)+'px 超过容器 '+mainSize+'px，会直接溢出'});
  else if((cfg.wrap||'nowrap')==='nowrap' && sum>mainSize+0.5)
    w.push({level:'warn', msg:'nowrap 下内容总长 '+round2(sum)+'px 超过容器 '+mainSize+'px，子项将被压缩'});
  if(cfg.alignContent && cfg.alignContent!=='stretch' && (cfg.wrap||'nowrap')==='nowrap')
    w.push({level:'warn', msg:'align-content 仅在 flex-wrap:wrap 多行时生效，当前为 nowrap'});
  if((cfg.justify==='space-between'||cfg.justify==='space-around') && norm.length<2)
    w.push({level:'warn', msg:'justify-content:'+cfg.justify+' 在只有 1 个子项时没有可见效果'});
  var pctBasis = norm.filter(function(x){ return typeof x.basis==='string' && /%$/.test(x.basis); });
  if(pctBasis.length && (cfg.wrap||'nowrap')==='wrap' && gap>0)
    w.push({level:'warn', msg:'百分比 flex-basis 不扣除 gap，'+pctBasis.length+' 个子项可能提前换行，建议改用 calc(50% - '+gap/2+'px)'});
  var growNoBasis = norm.filter(function(x){ return x.grow>0 && x.basis==='auto'; });
  if(growNoBasis.length>1)
    w.push({level:'info', msg:growNoBasis.length+' 个子项使用 flex-grow + basis:auto，最终宽度受内容影响；要等分请用 flex:1 1 0'});
  if(norm.some(function(x){ return x.order!==0; }))
    w.push({level:'info', msg:'使用了 order 会让视觉顺序与 DOM 顺序不一致，键盘 Tab 与读屏仍按 DOM 顺序'});
  return w;
}

var FlexboxForgePure = {
  parseFlex:parseFlex, resolveBasis:resolveBasis, normItems:normItems, orderItems:orderItems,
  breakLines:breakLines, flexLine:flexLine, distribute:distribute, layout:layout,
  containerCss:containerCss, itemCss:itemCss, fullCss:fullCss, lint:lint
};
if (typeof module !== 'undefined' && module.exports) module.exports = FlexboxForgePure;
if (typeof window !== 'undefined') window.FlexboxForgePure = FlexboxForgePure;
